/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { DiscreteDistributionHandmade, E, FlorySchulzDistribution, GeometricDistribution, HermiteDistribution, Lambda, LogarithmicDistribution, NegativeBinomialDistribution, Or, P, PoissonDistribution, Pow, RandomSymbol, Relational, SingleDiscretePSpace, SkellamDistribution, Sym, YuleSimonDistribution, ZetaDistribution, add, expand, expectation, finiteSet, fn, mul, piecewise, pow, pprint, pprintUseUnicode, rational, simplify, variance } from '../../src';
import { sympyStr, text } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.stats.drv_types", () => {
  it("E(X)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new DiscreteDistributionHandmade([Lambda([x], piecewise([rational(1, 10), Or(Relational(x, rational(0), '==', { evaluate: false }), Relational(x, rational(1), '==', { evaluate: false }), Relational(x, rational(2), '==', { evaluate: false }), Relational(x, rational(3), '==', { evaluate: false }), Relational(x, rational(4), '==', { evaluate: false }), Relational(x, rational(5), '==', { evaluate: false }), Relational(x, rational(6), '==', { evaluate: false }), Relational(x, rational(7), '==', { evaluate: false }), Relational(x, rational(8), '==', { evaluate: false }), Relational(x, rational(9), '==', { evaluate: false }))], [rational(0), true], { evaluate: false })), finiteSet(rational(0), rational(1), rational(2), rational(3), rational(4), rational(5), rational(6), rational(7), rational(8), rational(9))])]))))).toBe('9/2');
  });
  it("P(X>3)", () => {
    const x = new Sym('x');
    expect(sympyStr(P(Relational(new RandomSymbol(x, new SingleDiscretePSpace([x, new DiscreteDistributionHandmade([Lambda([x], piecewise([rational(1, 10), Or(Relational(x, rational(0), '==', { evaluate: false }), Relational(x, rational(1), '==', { evaluate: false }), Relational(x, rational(2), '==', { evaluate: false }), Relational(x, rational(3), '==', { evaluate: false }), Relational(x, rational(4), '==', { evaluate: false }), Relational(x, rational(5), '==', { evaluate: false }), Relational(x, rational(6), '==', { evaluate: false }), Relational(x, rational(7), '==', { evaluate: false }), Relational(x, rational(8), '==', { evaluate: false }), Relational(x, rational(9), '==', { evaluate: false }))], [rational(0), true], { evaluate: false })), finiteSet(rational(0), rational(1), rational(2), rational(3), rational(4), rational(5), rational(6), rational(7), rational(8), rational(9))])])), rational(3), '>', { evaluate: false })))).toBe('3/5');
  });
  it("density(X)(z)", () => {
    const z = new Sym('z');
    expect(sympyStr(new FlorySchulzDistribution([rational(1, 5)]).call(z))).toBe('(4/5)**(z - 1)*z/25');
  });
  it("E(X) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new FlorySchulzDistribution([rational(1, 5)])]))))).toBe('9');
  });
  it("variance(X)", () => {
    const x = new Sym('x');
    expect(sympyStr(variance(new RandomSymbol(x, new SingleDiscretePSpace([x, new FlorySchulzDistribution([rational(1, 5)])]))))).toBe('40');
  });
  it("density(X)(z) (2)", () => {
    const z = new Sym('z');
    expect(sympyStr(new GeometricDistribution([rational(1, 5)]).call(z))).toBe('(4/5)**(z - 1)/5');
  });
  it("E(X) (3)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new GeometricDistribution([rational(1, 5)])]))))).toBe('5');
  });
  it("variance(X) (2)", () => {
    const x = new Sym('x');
    expect(sympyStr(variance(new RandomSymbol(x, new SingleDiscretePSpace([x, new GeometricDistribution([rational(1, 5)])]))))).toBe('20');
  });
  it("density(H)(2)", () => {
    expect(sympyStr(new HermiteDistribution([rational(5), rational(4)]).call(rational(2)))).toBe('33*exp(-9)/2');
  });
  it("E(H)", () => {
    const H = new Sym('H');
    expect(sympyStr(expectation(new RandomSymbol(H, new SingleDiscretePSpace([H, new HermiteDistribution([rational(5), rational(4)])]))))).toBe('13');
  });
  it("variance(H)", () => {
    const H = new Sym('H');
    expect(sympyStr(variance(new RandomSymbol(H, new SingleDiscretePSpace([H, new HermiteDistribution([rational(5), rational(4)])]))))).toBe('21');
  });
  it("density(X)(z) (3)", () => {
    const z = new Sym('z');
    expect(equivalent(sympyStr(new LogarithmicDistribution([rational(1, 5)]).call(z)), '-1/(5**z*z*log(4/5))', [z], { fn: '.__call__', input: 'LogarithmicDistribution(1/5)' })).toBe(true);
  });
  it("E(X) (4)", () => {
    const x = new Sym('x');
    expect(equivalent(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new LogarithmicDistribution([rational(1, 5)])])))), '-1/(-4*log(5) + 8*log(2))', [x], { fn: 'E', input: 'x' })).toBe(true);
  });
  it("variance(X) (3)", () => {
    const x = new Sym('x');
    expect(equivalent(sympyStr(variance(new RandomSymbol(x, new SingleDiscretePSpace([x, new LogarithmicDistribution([rational(1, 5)])])))), '-1/((-4*log(5) + 8*log(2))*(-2*log(5) + 4*log(2))) + 1/(-64*log(2)*log(5) + 64*log(2)**2 + 16*log(5)**2) - 10/(-32*log(5) + 64*log(2))', [x], { fn: 'variance', input: 'x' })).toBe(true);
  });
  it("density(X)(z) (4)", () => {
    const z = new Sym('z');
    expect(sympyStr(new NegativeBinomialDistribution([rational(5), rational(1, 3)]).call(z))).toBe('(2/3)**z*binomial(z + 4, z)/243');
  });
  it("E(X) (5)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new NegativeBinomialDistribution([rational(5), rational(1, 3)])]))))).toBe('10');
  });
  it("variance(X) (4)", () => {
    const x = new Sym('x');
    expect(sympyStr(variance(new RandomSymbol(x, new SingleDiscretePSpace([x, new NegativeBinomialDistribution([rational(5), rational(1, 3)])]))))).toBe('30');
  });
  it("density(X)(z) (5)", () => {
    const z = new Sym('z');
    const lambda = new Sym('lambda', { positive: true });
    expect(sympyStr(new PoissonDistribution([lambda]).call(z))).toBe('lambda**z*exp(-lambda)/factorial(z)');
  });
  it("E(X) (6)", () => {
    const x = new Sym('x');
    const lambda = new Sym('lambda', { positive: true });
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new PoissonDistribution([lambda])]))))).toBe('lambda');
  });
  it("simplify(variance(X))", () => {
    const lambda = new Sym('lambda', { positive: true });
    expect(sympyStr(simplify(lambda, { inverse: false, rational: false, doit: true }))).toBe('lambda');
  });
  it("pprint(density(X)(z), use_unicode=False)", () => {
    const mu1 = new Sym('mu1', { positive: true });
    const mu2 = new Sym('mu2', { positive: true });
    const z = new Sym('z', { integer: true });
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(pprint(mul(pow(mul(mu1, pow(mu2, -1)), mul(rational(1, 2), z)), fn('besseli', [z, mul(2, pow(mu1, rational(1, 2)), pow(mu2, rational(1, 2)))]), new Pow(E, add(mul(-1, mu1), mul(-1, mu2)))), { useUnicode: false }))).toBe('     z                                          \n     -                                          \n     2                                          \n/mu1\\   -mu1 - mu2        /       _____   _____\\\n|---| *e          *besseli\\z, 2*\\/ mu1 *\\/ mu2 /\n\\mu2/                                           ');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("E(X) (7)", () => {
    const x = new Sym('x');
    const mu1 = new Sym('mu1', { positive: true });
    const mu2 = new Sym('mu2', { positive: true });
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new SkellamDistribution([mu1, mu2])]))))).toBe('mu1 - mu2');
  });
  it("variance(X).expand()", () => {
    const mu1 = new Sym('mu1', { positive: true });
    const mu2 = new Sym('mu2', { positive: true });
    expect(sympyStr(expand(add(mu1, mu2, mul(2, pow(mu1, 2)), mul(2, pow(mu2, 2)), mul(add(mu1, mul(-1, mu2)), add(mul(-2, mu1), mul(2, mu2))), mul(-4, mu1, mu2)), {}))).toBe('mu1 + mu2');
  });
  it("density(X)(z) (6)", () => {
    const z = new Sym('z');
    expect(sympyStr(new YuleSimonDistribution([rational(5)]).call(z))).toBe('5*beta(z, 6)');
  });
  it("simplify(E(X))", () => {
    expect(sympyStr(simplify(rational(5, 4), { inverse: false, rational: false, doit: true }))).toBe('5/4');
  });
  it("simplify(variance(X)) (2)", () => {
    expect(sympyStr(simplify(rational(25, 48), { inverse: false, rational: false, doit: true }))).toBe('25/48');
  });
  it("density(X)(z) (7)", () => {
    const z = new Sym('z');
    expect(sympyStr(new ZetaDistribution([rational(5)]).call(z))).toBe('1/(z**5*zeta(5))');
  });
  it("E(X) (8)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new ZetaDistribution([rational(5)])]))))).toBe('pi**4/(90*zeta(5))');
  });
  it("variance(X) (5)", () => {
    const x = new Sym('x');
    expect(sympyStr(variance(new RandomSymbol(x, new SingleDiscretePSpace([x, new ZetaDistribution([rational(5)])]))))).toBe('-pi**8/(8100*zeta(5)**2) + zeta(3)/zeta(5)');
  });
});
